-- Regression checks; always roll back. No external calls or real records.
begin;
set local role service_role;
do $$
declare c jsonb;b jsonb;b2 jsonb;id1 uuid:=gen_random_uuid();id2 uuid:=gen_random_uuid();id3 uuid:=gen_random_uuid();
 contact jsonb:='{"firstName":"Fictional","lastName":"Booker","email":"iftari-fixture@example.invalid","mobile":"+447700900123"}';
 qty jsonb:='{"member":2,"nonmember":1,"child":2,"under5":0}';emails text[]:=array['iftari-fixture@example.invalid'];raised boolean;
begin
 assert not has_table_privilege('anon','public.icsh_iftari_bookings','select');
 assert not has_table_privilege('authenticated','public.icsh_iftari_bookings','select');
 assert not has_function_privilege('anon','public.icsh_iftari_reserve(uuid,text,text,jsonb,jsonb,text[],integer,integer,integer,text,text)','execute');
 select configuration into c from public.icsh_iftari_settings where slug='ramadan-iftari-2027';
 -- A private draft cannot be booked.
 raised:=false;
 begin perform public.icsh_iftari_reserve(id1,repeat('a',64),repeat('b',64),contact,qty,emails,1000,(c->>'version')::integer,11500,'acct_fixture','test');
 exception when sqlstate 'P2702' then raised:=true;end;assert raised,'draft blocked';
 c:=public.icsh_iftari_configure(c||'{"status":"published","capacity":6}',(c->>'version')::integer);
 raised:=false;
 begin perform public.icsh_iftari_reserve(id2,repeat('a',64),repeat('b',64),contact,qty,array['guest@example.invalid'],1000,(c->>'version')::integer,11500,'acct_fixture','test');
 exception when sqlstate '22023' then raised:=true;end;assert raised,'another attendee email cannot grant a lead-booker discount';
 raised:=false;
 begin perform public.icsh_iftari_reserve(id2,repeat('a',64),repeat('b',64),contact,qty,array[emails[1],emails[1]],1000,(c->>'version')::integer,11500,'acct_fixture','test');
 exception when sqlstate '22023' then raised:=true;end;assert raised,'multiple member tickets consume one lead email claim';

 b:=public.icsh_iftari_reserve(id1,repeat('a',64),repeat('b',64),contact,qty,emails,1000,(c->>'version')::integer,11500,'acct_fixture','test');
 assert (b->>'total')::integer=11500 and (b->'quote'->>'tickets')::integer=10500 and (b->'quote'->>'donation')::integer=1000,'authoritative £115 quote';
 assert b->>'status'='pending' and b->>'paid_at' is null,'pending is not confirmed';
 assert jsonb_array_length(b->'quote'->'lines')=4,'separate lines';
 b2:=public.icsh_iftari_reserve(id1,repeat('a',64),repeat('b',64),contact,qty,emails,1000,1,1,'acct_fixture','test');
 assert b2=b,'idempotent replay preserves original booking even after settings change';
 raised:=false;
 begin perform public.icsh_iftari_reserve(id1,repeat('c',64),repeat('b',64),contact,qty,emails,1000,(c->>'version')::integer,11500,'acct_fixture','test');
 exception when sqlstate 'P2701' then raised:=true;end;assert raised,'changed request rejected';
 raised:=false;
 begin perform public.icsh_iftari_reserve(id2,repeat('a',64),repeat('b',64),contact,'{"member":0,"nonmember":2,"child":0,"under5":0}',array[]::text[],0,(c->>'version')::integer,5600,'acct_fixture','test');
 exception when sqlstate 'P2705' then raised:=true;end;assert raised,'capacity includes all pending guests';
 raised:=false;
 begin perform public.icsh_iftari_reserve(id2,repeat('a',64),repeat('b',64),contact,'{"member":1,"nonmember":0,"child":0,"under5":0}',array[emails[1]],0,(c->>'version')::integer,2550,'acct_fixture','test');
 exception when sqlstate 'P2706' then raised:=true;end;assert raised,'member email protected across bookings';
 raised:=false;
 begin perform public.icsh_iftari_reserve(id2,repeat('a',64),repeat('b',64),contact,'{"member":0,"nonmember":0,"child":0,"under5":1}',array[]::text[],0,(c->>'version')::integer,1,'acct_fixture','test');
 exception when sqlstate 'P2704' then raised:=true;end;assert raised,'unknown under-5 price is not free';
 raised:=false;
 begin perform public.icsh_iftari_configure(c||'{"capacity":4}',(c->>'version')::integer);
 exception when sqlstate 'P2705' then raised:=true;end;assert raised,'cannot reduce capacity below holds';
 assert public.icsh_iftari_attach(id1,'cs_test_fixtureSession123','acct_fixture','test');
 assert public.icsh_iftari_record(id1,'cs_test_fixtureSession123','acct_fixture','test','evt_iftaripending','checkout.session.completed','pending',11500,null,null,null,0);
 assert (select status='pending' from public.icsh_iftari_bookings where id=id1),'unpaid completion cannot confirm';
 assert not exists(select 1 from public.icsh_form_emails where source_id=id1),'no email before payment';
 assert public.icsh_iftari_record(id1,'cs_test_fixtureSession123','acct_fixture','test','evt_iftaripaid','checkout.session.async_payment_succeeded','paid',11500,'pi_fixture','ch_fixture',now(),0);
 assert (select status='paid' and paid_at is not null from public.icsh_iftari_bookings where id=id1),'verified async success confirms';
 assert public.icsh_iftari_record(id1,'cs_test_fixtureSession123','acct_fixture','test','evt_iftaripaid','checkout.session.async_payment_succeeded','paid',11500,'pi_fixture','ch_fixture',now(),0);
 assert (select count(*)=1 from public.icsh_iftari_payment_events where event_id='evt_iftaripaid'),'replay records event once';
 assert public.icsh_iftari_record(id1,'cs_test_fixtureSession123','acct_fixture','test','evt_iftariexpiredlate','checkout.session.expired','expired',11500,null,null,null,0);
 assert (select status='paid' from public.icsh_iftari_bookings where id=id1),'late expiry cannot downgrade payment';
 assert not exists(select 1 from public.icsh_form_emails where source_id=id1),'test payments never send confirmations';
 c:=public.icsh_iftari_configure(c||'{"allowRepeatMemberDiscounts":true}',(c->>'version')::integer);
 b2:=public.icsh_iftari_reserve(id2,repeat('a',64),repeat('b',64),contact,'{"member":1,"nonmember":0,"child":0,"under5":0}',array[emails[1]],0,(c->>'version')::integer,2550,'acct_fixture','test');
 assert b2->>'status'='pending','explicit organiser override permits repeat discount';
 perform public.icsh_iftari_attach(id2,'cs_test_secondSession123','acct_fixture','test');
 perform public.icsh_iftari_record(id2,'cs_test_secondSession123','acct_fixture','test','evt_iftariexpired','checkout.session.expired','expired',2550,null,null,null,0);
 assert (select status='expired' from public.icsh_iftari_bookings where id=id2),'verified expiry releases reservation';
 -- Confirm outbox semantics with fictional live input inside this rollback-only transaction.
 update public.icsh_form_email_settings set enabled=true where id;
 b2:=public.icsh_iftari_reserve(id3,repeat('a',64),repeat('b',64),contact,'{"member":0,"nonmember":1,"child":0,"under5":0}',array[]::text[],0,(c->>'version')::integer,2800,'acct_fixture','live');
 assert not exists(select 1 from public.icsh_form_emails where source_id=id3),'save does not queue payment confirmation';
 perform public.icsh_iftari_attach(id3,'cs_live_fixtureSession123','acct_fixture','live');
 perform public.icsh_iftari_record(id3,'cs_live_fixtureSession123','acct_fixture','live','evt_iftarilivepaid','checkout.session.completed','paid',2800,'pi_fixtureLive','ch_fixtureLive',now(),0);
 assert (select count(*)=1 from public.icsh_form_emails where source_table='icsh_iftari_bookings' and source_id=id3),'paid confirmation queued once';
 perform public.icsh_iftari_record(id3,'cs_live_fixtureSession123','acct_fixture','live','evt_iftarilivereplay','checkout.session.async_payment_succeeded','paid',2800,'pi_fixtureLive','ch_fixtureLive',now(),0);
 assert (select count(*)=1 from public.icsh_form_emails where source_table='icsh_iftari_bookings' and source_id=id3),'second success event cannot duplicate email';
 raised:=false;
 begin perform public.icsh_iftari_record(id3,'cs_live_fixtureSession123','acct_wrong','live','evt_bad','checkout.session.completed','paid',2800,'pi_fixtureLive','ch_fixtureLive',now(),0);
 exception when sqlstate '22023' then raised:=true;end;assert raised,'wrong account rejected';
end $$;
rollback;
